import pytest
from ta_attenuator.attenuator import RfPathAlreadyUsed
from ta_attenuator.attenuator import ReleasingNotReservedPort
from ta_attenuator.attenuator import ChangingAttenutionValueOfNotReservedPort


def reserving_ports_on_attenuator_success(attenuator_object):
    number_of_ports_reserved_before = len(attenuator_object.used_ports)
    number_of_ports_to_reserve = 5
    for port in range(1, number_of_ports_to_reserve+1):
        attenuator_object.reserve_port(port)
    number_of_ports_reserved_after = len(attenuator_object.used_ports)
    assert(number_of_ports_reserved_after - number_of_ports_reserved_before == number_of_ports_to_reserve)


def reserving_ports_on_attenuator_duplicate_id(attenuator_object):
    port_number = 1
    attenuator_object.reserve_port(port_number)
    with pytest.raises(RfPathAlreadyUsed):
        attenuator_object.reserve_port(port_number)


def setting_attenuation_value_on_not_reserved_port(attenuator_object):
    port_to_reserve = 1
    port_to_set_att_value = 2
    attenuation_value = '40 db'
    attenuator_object.reserve_port(port_to_reserve)
    assert attenuator_object.used_ports == [port_to_reserve]
    with pytest.raises(ChangingAttenutionValueOfNotReservedPort):
        attenuator_object.set_single_rf_path_attenuation(port_to_set_att_value, attenuation_value)


def releasing_ports_on_attenuator_success(attenuator_object):
    ports_to_reserve = [1, 2, 3, 4, 5]
    ports_to_release = [1, 2, 3]
    for port in ports_to_reserve:
        attenuator_object.reserve_port(port)
    for port in ports_to_release:
        attenuator_object.release_port(port)
    assert attenuator_object.used_ports == [4, 5]


def releasing_not_reserved_port_on_attenuator_causes_exception(attenuator_object):
    attenuator_object.reserve_port(1)
    assert len(attenuator_object.used_ports) == 1
    with pytest.raises(ReleasingNotReservedPort):
        attenuator_object.release_port(2)
